guidance.correct_example:
def fetch_user(a_id: int) -> Result[User]:
    user = db.query(a_id)
    if user is None:
        return Result.failure(f'User {a_id} not found')
    return Result.success(user)

guidance.incorrect_example:
def fetch_user(a_id: int) -> tuple[bool, User | None, str]:
    user = db.query(a_id)
    if user is None:
        return (False, None, 'User not found')
    return (True, user, 'Success')
